    black_squares = [(r, c) for r in range(5) for c in range(5) if (r + c) % 2 == 0]

    def get_trominoes(r, c):
        # All L-trominos that include (r,c) and are within the 5x5 board.
        # An L-tromino is a 2x2 block minus one square.
        # Let's find all 2x2 blocks that contain (r,c).
        trominos = []
        for dr in [-1, 0]:
            for dc in [-1, 0]:
                r0, c0 = r + dr, c + dc
                if 0 <= r0 < 4 and 0 <= c0 < 4:
                    # This 2x2 block is {(r0,c0), (r0+1,c0), (r0,c0+1), (r0+1,c0+1)}
                    coords = [(r0, c0), (r0+1, c0), (r0, c0+1), (r0+1, c0+1)]
                    for i in range(4):
                        tromino = [coords[j] for j in range(4) if j != i]
                        if (r, c) in tromino:
                            trominos.append(tuple(sorted(tromino)))
        return list(set(trominos))

    def backtrack(covered_black_count, current_board, trominos_count, target_trominos):
        if covered_black_count == len(black_squares):
            return True
        if trominos_count == target_trominos:
            return False

