def is_tileable(board_size, empty_squares):
    # board_size is n
    # empty_squares is a set of (r,c)
    board = [[True for _ in range(board_size)] for _ in range(board_size)]
    for r, c in empty_squares:
        board[r][c] = False

    # All squares to be covered
    targets = []
    for r in range(board_size):
        for c in range(board_size):
            if board[r][c]:
                targets.append((r, c))

    if len(targets) % 3 != 0:
        return False

    num_trominos = len(targets) // 3

    def backtrack(count):
        if count == num_trominos:
            return True

        # Find first available square
        r, c = -1, -1
        for i in range(board_size):
            for j in range(board_size):
                if board[i][j]:
                    r, c = i, j
                    break
            if r != -1: break

        # Try all L-trominos that cover (r,c)
        # An L-tromino is a 2x2 block minus one square.
        # The 2x2 block containing (r,c) can have its top-left at (r-1,c-1), (r-1,c), (r,c-1), (r,c)
        for dr in [-1, 0]:
            for dc in [-1, 0]:
                r0, c0 = r + dr, c + dc
                if 0 <= r0 < board_size - 1 and 0 <= c0 < board_size - 1:
                    coords = [(r0, c0), (r0+1, c0), (r0, c0+1), (r0+1, c0+1)]
